fn test_mlkem_all_upstream_seed_public_der_fixtures() {
	subtle := SubtleCrypto.create()
	for fixture in mlkem_source_fixtures {
		key := subtle.import_key(.raw_seed, hex.decode(fixture.seed_hex)!, fixture.name, true, [.decapsulate_bits], '')!
		handle := key.internal_handle() as MlkemPrivateKeyHandle
		assert handle.public_key.hex() == fixture.public_hex
		assert handle.seed.hex() == fixture.seed_hex
		// Translate the current ASN.1 Decoder nesting even in the constructed
		// expandedKey/both branches, rather than replacing it with a new parser.
		expanded := okp_der_value(0x24, okp_der_value(0x04, handle.private_key))
		expanded_key := subtle.import_key(.pkcs8, wrap_no_parameter_key_info(mlkem_oid_bytes(fixture.name)!, expanded, true), fixture.name, true, [.decapsulate_bits], '')!
		assert (expanded_key.internal_handle() as MlkemPrivateKeyHandle).private_key == handle.private_key
		mut both_seed_scope := okp_der_value(0x04, handle.seed)
		both_seed_scope << okp_der_value(0x24, expanded)
		both := okp_der_value(0x30, okp_der_value(0x24, both_seed_scope))
		both_key := subtle.import_key(.pkcs8, wrap_no_parameter_key_info(mlkem_oid_bytes(fixture.name)!, both, true), fixture.name, true, [.decapsulate_bits], '')!
		assert (both_key.internal_handle() as MlkemPrivateKeyHandle).private_key == handle.private_key
		assert subtle.export_key(.pkcs8, key)!.hex() == fixture.pkcs8_hex
		assert subtle.export_key(.raw_seed, key)!.hex() == fixture.seed_hex
		der_key := subtle.import_key(.pkcs8, hex.decode(fixture.pkcs8_hex)!, fixture.name, true, [.decapsulate_bits], '')!
		assert (der_key.internal_handle() as MlkemPrivateKeyHandle).private_key == handle.private_key
		public_key := subtle.import_key(.raw_public, hex.decode(fixture.public_hex)!, fixture.name, true, [.encapsulate_bits], '')!
		assert public_key.internal_handle() is MlkemPublicKeyHandle
		assert subtle.export_key(.spki, public_key)!.hex() == fixture.spki_hex
		assert subtle.import_key(.spki, hex.decode(fixture.spki_hex)!, fixture.name, true, [.encapsulate_bits], '')!.handle() == public_key.handle()
		assert subtle.export_key(.raw_public, public_key)!.hex() == fixture.public_hex
	}
}

fn test_mlkem_upstream_fixed_decapsulation_vectors_and_real_roundtrip() {
	subtle := SubtleCrypto.create()
	for vector in mlkem_decapsulation_vectors {
		private_key := subtle.import_key(.raw_seed, hex.decode(vector.seed_hex)!, vector.name, true, [.decapsulate_bits], '')!
		assert (private_key.internal_handle() as MlkemPrivateKeyHandle).public_key.hex() == vector.public_hex
		assert subtle.decapsulate_bits(vector.name, private_key, hex.decode(vector.ciphertext_hex)!)!.hex() == vector.shared_hex
		public_key := subtle.import_key(.raw_public, hex.decode(vector.public_hex)!, vector.name, true, [.encapsulate_bits], '')!
		encapsulation := subtle.encapsulate_bits(vector.name, public_key)!
		shared_bytes := encapsulation.shared_key or { panic('shared') }
		ciphertext := encapsulation.ciphertext or { panic('ciphertext') }
		_, _, cipher_size := mlkem_sizes(vector.name)!
		assert shared_bytes.len == 32 && ciphertext.len == cipher_size
		assert subtle.decapsulate_bits(vector.name, private_key, ciphertext)! == shared_bytes
		mut tampered := ciphertext.clone()
		tampered[0] ^= 1
		// FIPS203 implicit rejection returns a different real secret for invalid ciphertext.
		assert subtle.decapsulate_bits(vector.name, private_key, tampered)! != shared_bytes
		if _ := subtle.decapsulate_bits(vector.name, private_key, ciphertext[..ciphertext.len - 1]) {
			assert false
		} else {
			assert err.msg().starts_with('OperationError: Key decapsulation failed:')
		}
	}
}

fn test_mlkem_generation_usages_key_variants_and_source_error_order() {
	subtle := SubtleCrypto.create()
	for name in ['ML-KEM-512', 'ML-KEM-768', 'ML-KEM-1024'] {
		pair := subtle.generate_key(AlgorithmParams{ name: name.to_lower() }, false, [
			.encapsulate_key,
			.decapsulate_key,
		])!.pair or { panic('pair') }
		assert pair.public_key.extractable && pair.public_key.usages == [.encapsulate_key]
		assert !pair.private_key.extractable && pair.private_key.usages == [.decapsulate_key]
		encapsulation := subtle.encapsulate_key(name, pair.public_key, 'AES-GCM', true, [.encrypt])!
		shared_key := encapsulation.shared_key or { panic('key') }
		decapsulated := subtle.decapsulate_key(name, pair.private_key, encapsulation.ciphertext or { panic('cipher') }, 'AES-GCM', true, [.encrypt])!
		assert shared_key.handle() == decapsulated.handle()
		for shared_name in ['AES-OCB', 'KMAC128', 'KMAC256'] {
			encapsulated_key := subtle.encapsulate_key(name, pair.public_key, shared_name, true, [])!
			secret := encapsulated_key.shared_key or { panic('shared key') }
			decoded := subtle.decapsulate_key(name, pair.private_key, encapsulated_key.ciphertext or { panic('ciphertext') }, shared_name, true, [])!
			assert secret.algorithm_name() == shared_name && secret.usages.len == 0
			assert secret.handle() == decoded.handle()
		}
		if _ := subtle.encapsulate_bits(name, pair.public_key) {
			assert false
		} else {
			assert err.msg().starts_with('InvalidAccessError:')
		}
	}
	if _ := subtle.generate_key(AlgorithmParams{ name: 'ML-KEM-512' }, true, [.verify]) {
		assert false
	} else {
		assert err.msg() == 'SyntaxError: Invalid key usage'
	}
	if _ := subtle.import_key(.raw_seed, [], 'ML-KEM-512', true, [.encapsulate_bits], '') {
		assert false
	} else {
		assert err.msg() == "SyntaxError: Invalid key usage 'encapsulateBits'"
	}
	if _ := subtle.import_key(.raw_seed, [], 'ML-KEM-512', true, [.decapsulate_bits], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: Invalid key format'
	}
	if _ := subtle.import_key(.raw, [], 'ML-KEM-512', true, [.encapsulate_bits], '') {
		assert false
	} else {
		assert err.msg() == 'NotSupportedError: Invalid key format'
	}
	if _ := subtle.import_jwk(JsonWebKey{}, 'ML-KEM-512', true, [.encapsulate_bits], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: Invalid key type'
	}
	malformed := subtle.import_key(.raw_public, [u8(1)], 'ML-KEM-512', true, [.encapsulate_bits], '')!
	assert malformed.handle() == [u8(1)]
	if _ := subtle.encapsulate_bits('ML-KEM-512', malformed) {
		assert false
	} else {
		assert err.msg().starts_with('OperationError: Key encapsulation failed:')
	}
	// Preserve source ENTER_TYPED_SCOPE behavior: ordinary primitive expandedKey
	// enters a non-constructed type and is rejected by the current upstream parser.
	der := wrap_no_parameter_key_info(mlkem_oid_bytes('ML-KEM-512')!, okp_der_value(0x04, []u8{len: 1632}), true)
	if _ := subtle.import_key(.pkcs8, der, 'ML-KEM-512', true, [.decapsulate_bits], '') {
		assert false
	} else {
		assert err.msg() == 'DataError: ASN1::Decoder: Entering a non-constructed type'
	}
}

@[heap]
struct MlkemBindingHost {
mut:
	work   []fn ()
	settle []fn ()
}

fn test_mlkem_promise_decapsulation_copies_ciphertext_and_uses_crypto_tasks() {
	mut host := &MlkemBindingHost{}
	binding := SubtleCryptoBinding.create(SubtleCrypto.create(), webidl.PromiseContext{}, fn [mut host] (task fn ()) {
		host.work << task
	}, fn [mut host] (task fn ()) { host.settle << task })
	vector := mlkem_decapsulation_vectors[0]
	key := SubtleCrypto.create().import_key(.raw_seed, hex.decode(vector.seed_hex)!, vector.name, true, [.decapsulate_bits], '')!
	mut ciphertext := webidl.BufferSource.array_buffer(hex.decode(vector.ciphertext_hex)!)
	promise := binding.decapsulate_bits(webidl.string_value(vector.name), key, ciphertext)
	ciphertext.write([]u8{len: int(ciphertext.byte_length())}, 0)!
	assert promise.state == .pending
	host.work[0]()
	assert promise.state == .pending && host.settle.len == 1
	host.settle[0]()
	assert promise.state == .fulfilled
	assert webidl.get_buffer_source_copy(promise.result.buffer_value or { panic('secret') }).hex() == vector.shared_hex
}

fn test_mlkem_jwk_roundtrips_and_rejects_invalid_metadata_or_key_material() {
	subtle := SubtleCrypto.create()
	for fixture in mlkem_source_fixtures {
		private_key := subtle.import_key(.raw_seed, hex.decode(fixture.seed_hex)!, fixture.name, true, [.decapsulate_bits], '')!
		private_jwk := subtle.export_jwk(private_key)!
		assert private_jwk.kty or { '' } == 'AKP'
		assert base64url_decode(private_jwk.pub_ or { '' })!.hex() == fixture.public_hex
		assert subtle.import_jwk(private_jwk, fixture.name, true, [.decapsulate_bits], '')!.handle() == private_key.handle()
		public_key := subtle.import_key(.raw_public, hex.decode(fixture.public_hex)!, fixture.name, true, [.encapsulate_bits], '')!
		public_jwk := subtle.export_jwk(public_key)!
		assert public_jwk.priv == none
		assert subtle.import_jwk(public_jwk, fixture.name, true, [.encapsulate_bits], '')!.handle() == public_key.handle()
		for invalid in [
			JsonWebKey{...public_jwk, kty: 'oct'},
			JsonWebKey{...public_jwk, alg: none},
			JsonWebKey{...public_jwk, alg: 'ML-KEM-invalid'},
			JsonWebKey{...public_jwk, use: 'sig'},
			JsonWebKey{...public_jwk, key_ops: ['decapsulateBits']},
			JsonWebKey{...public_jwk, ext: false},
			JsonWebKey{...public_jwk, pub_: base64url_encode([u8(1)])},
		] {
			if _ := subtle.import_jwk(invalid, fixture.name, true, [.encapsulate_bits], '') { assert false }
			else { assert err.msg().starts_with('DataError:') }
		}
		for invalid in [JsonWebKey{...private_jwk, priv: base64url_encode([u8(1)])}, JsonWebKey{...private_jwk, pub_: base64url_encode([]u8{len: hex.decode(fixture.public_hex)!.len})}] {
			if _ := subtle.import_jwk(invalid, fixture.name, true, [.decapsulate_bits], '') { assert false }
			else { assert err.msg().starts_with('DataError:') }
		}
	}
}

fn test_mlkem_async_key_methods_use_key_usage_and_source_shared_import_rules() {
	mut host := &MlkemBindingHost{}
	binding := SubtleCryptoBinding.create(SubtleCrypto.create(), webidl.PromiseContext{}, fn [mut host] (task fn ()) {
		host.work << task
	}, fn [mut host] (task fn ()) { host.settle << task })
	fixture := mlkem_source_fixtures[1]
	subtle := SubtleCrypto.create()
	public_key := subtle.import_key(.raw_public, hex.decode(fixture.public_hex)!, fixture.name, true, [.encapsulate_key], '')!
	private_key := subtle.import_key(.raw_seed, hex.decode(fixture.seed_hex)!, fixture.name, true, [.decapsulate_key], '')!
	// Source KEM key methods directly invoke import and permit empty shared usages.
	encapsulated := binding.encapsulate_key(webidl.string_value(fixture.name), public_key, webidl.string_value('AES-GCM'), true, [])
	host.work[0]()
	assert encapsulated.state == .pending
	host.settle[0]()
	assert encapsulated.state == .fulfilled
	shared_key := crypto_key_from_value(encapsulated.result.object_value['sharedKey'])!
	assert shared_key.usages.len == 0 && shared_key.handle().len == 32
	ciphertext := encapsulated.result.object_value['ciphertext'].buffer_value or { panic('ciphertext') }
	decapsulated := binding.decapsulate_key(webidl.string_value(fixture.name), private_key, ciphertext, webidl.string_value('AES-GCM'), true, [])
	host.work[1]()
	assert decapsulated.state == .pending
	host.settle[1]()
	assert decapsulated.state == .fulfilled
	assert crypto_key_from_value(decapsulated.result)!.handle() == shared_key.handle()
	// The public importKey still applies its common empty-secret-usages check.
	imported := binding.import_key(.raw, webidl.buffer_source_value(webidl.BufferSource.array_buffer([]u8{len: 32})), webidl.string_value('AES-GCM'), true, [])
	host.work[2]()
	assert imported.state == .rejected
	assert imported.result.object_value['name'].string_value == 'SyntaxError'
}
